import{_ as t,c as s,o as p,ah as o,ao as i,ap as a}from"./chunks/framework.Dq2_gudl.js";const b=JSON.parse('{"title":"Разрешение горевать — Бог хранит ваши слёзы в сосуде","description":"Плакать о питомце — не недостаток веры. Псалмы говорят, что Бог собирает наши слёзы в сосуд и записывает их в книгу.","frontmatter":{"title":"Разрешение горевать — Бог хранит ваши слёзы в сосуде","description":"Плакать о питомце — не недостаток веры. Псалмы говорят, что Бог собирает наши слёзы в сосуд и записывает их в книгу."},"headers":[],"relativePath":"ru/pets-in-heaven/permission-to-grieve.md","filePath":"ru/pets-in-heaven/permission-to-grieve.md"}'),n={name:"ru/pets-in-heaven/permission-to-grieve.md"};function l(r,e,c,h,m,d){return p(),s("div",null,[...e[0]||(e[0]=[o('<div class="pl-quote"><p>«Прошло уже несколько месяцев, а я всё плачу. Я недостаточно сильный? У меня слишком слабая вера?»</p><p class="pl-quote-soft">Библия никогда не считает слёзы доказательством провала. Как раз наоборот.</p></div><section class="pl-section"><h2>1. Бог хранит слёзы в сосуде</h2><blockquote><p><strong>Псалом 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>Давид написал это из глубокого страдания. Он просит Бога собрать его слёзы в сосуд и записать их в книгу — в древности сосуд со слезами был драгоценной коллекцией, доказательством, что «этот человек плакал об этом».</p><p>Что это значит: <strong>ваши слёзы — не то, что просто падает и исчезает.</strong> Ни одна капля не потеряна. Каждая слеза, пролитая о нём, собрана. Записана.</p><p>Поэтому когда вы думаете «может, я плачу слишком много?» — помните: для Бога это не шум. Это запись.</p></section><section class="pl-section"><h2>2. Бог приближается к сокрушённым — Он не отчитывает их</h2><blockquote><p><strong>Псалом 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>Псалом 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>Обратите внимание на глаголы: Он <em>приближается</em>. Он <em>исцеляет</em>. Он <em>перевязывает</em>. Первое, что Бог делает для скорбящего, — не требует взять себя в руки, а подходит к нему.</p><p>Иисус тоже сказал одну короткую фразу:</p><blockquote><p><strong>Матфея 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>«Блаженны плачущие.» Скорбящих не упрекают — их называют блаженными, потому что утешение придёт. Не «тебе следует радоваться», а «ты получишь утешение».</p></section><section class="pl-section"><h2>3. Горе — не противоположность любви, а её продолжение</h2><p>Мы не плачем о том, что никогда не любили. Именно потому, что между вами действительно была любовь, сейчас так больно.</p><p>Бог создал нас существами, которые плачут о потерях. Сам Иисус плакал у гробницы Лазаря (Иоанна 11:35) — зная, что через несколько минут воскресит его, Он всё равно плакал.</p><p>Так что вы не должны никому извиняться за свои слёзы. У вас не мало веры. Вы просто ранены в любви.</p><p class="pl-quote-soft">Если хотите, можете помолиться так:</p></section><div class="pl-quote"><p>«Господи, Ты знаешь, сколько раз я плакал.<br>Спасибо, что не торопишь меня стать прежним и хранишь каждую слезу в Своём сосуде.<br>Приблизься ко мне, как Ты приближаешься ко всякому сокрушённому сердцу;<br>исцели меня и позаботься о том, кого я потерял.<br>Сегодня я не хочу быть сильным. Я хочу только, чтобы Ты меня обнял. Аминь.»</p></div><section class="pl-section"><h2>Четыре вещи, которые можно сделать для себя прямо сейчас</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>Не решайте ничего на пике</h3><p>Волны горя проходят. В худший момент достаточно пережить следующие пять минут. Больше ничего не решайте.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>Сначала позаботьтесь о теле</h3><p>Попейте воды. Поешьте. Поспите. Горе истощает тело, а голодное тело делает боль сердца сильнее.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Запишите его в блокнот</h3><p>Не нужно красиво. Запишите одну деталь: как он будил вас, какое выражение лица вам нравилось. Дайте тоске место, где жить.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>Найдите того, кто действительно понимает</h3><p>Не все понимают слёзы о животном, но некоторые понимают. Если такого нет — напишите. Бог прочитает.</p></div></div></section><section class="pl-section"><h2>Тот день придёт</h2><p>Откровение обещает, что однажды Сам Бог отрёт всякую слезу с наших глаз, и не будет больше ни смерти, ни печали, ни вопля, ни боли (Откровение 21:4). В тот день вы увидите, что каждая слеза, пролитая о нём, была и запомнена, и услышана благим Богом.</p><p>А до тех пор — разрешите себе горевать. Это ещё один способ всё ещё любить его.</p><p><a href="/ru/pets-in-heaven/">← Вернуться к Pets in Heaven</a> ｜ Первое чтение: <a href="/ru/pets-in-heaven/will-i-see-my-pet-again">Увижу ли я его снова?</a></p></section><div class="pl-cta"><h2>Сегодня достаточно одной фразы.</h2><p>В PetLoss есть дневник с подсказками и спутник SOS, который даёт опорные слова в самые тяжёлые моменты. Без аккаунта, без загрузок, полностью офлайн.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Скачать в App Store</a></div><div class="pl-bible"><h3>Пусть слово Писания остаётся с вами</h3><p>Все стихи в этой статье — из Библии. С приложением Rainbow Bible вы можете читать Писание в любое время и настроить виджет со стихом дня — небольшой свет для дней, когда вы скучаете.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Виджет Rainbow Bible со стихом 2 Тимофею 2:13" loading="lazy"><figcaption>Стих дня на главном экране</figcaption></figure><figure><img src="'+a+'" alt="Rainbow Bible — тема «Питомцы на небесах» со стихом Матфея 10:29-31" loading="lazy"><figcaption>Читайте Писание в теме «Питомцы на небесах»</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Скачать Rainbow Bible в App Store</a></div>',9)])])}const v=t(n,[["render",l]]);export{b as __pageData,v as default};
